select count(*) from tr where match('error') and gid=1; show meta like 'index';
select count(*), max(gid) from tr where match('error') and gid=1; show meta like 'index';

create table tz ( body text ) morphology='none' html_strip='1' index_zones='h1';
insert into tz ( id, body ) values ( 1, '<h1>error</h1> failed' ), ( 2, 'error <h1>failed</h1>' );
select count(*) from tz where match('ZONE:h1 error'); show meta like 'index';
select count(*), max(id) from tz where match('ZONE:h1 error'); show meta like 'index';
select count(*) from tz where match('error failed'); show meta like 'index';
